// Jachi Health account deletion. Netlify Function: POST /api/account/delete
// GENERATED by build.py from src/functions/lib.mjs and src/functions/account.mjs. Edit those, then run
// `python3 build.py`. Never put a key or token in these files: they live in Netlify's environment variables.
const SUPPORT_EMAIL = "support@jachihealth.com";

// ---------- Shared by the account and admin functions (src/functions/lib.mjs) ----------
// Netlify Identity: this site's own user service. Netlify gives functions its address and a short-lived
// operator token (globalThis.netlifyIdentityContext) for admin actions like listing or deleting users.
// Netlify Forms: read and deleted through the Netlify API with NETLIFY_API_TOKEN, a personal access token
// kept in Netlify's environment variables (never in this repository).
const ALLOWED_HOSTS = /(^|\.)jachihealth\.com$|^localhost$|^127\.0\.0\.1$/;
const NETLIFY_API = 'https://api.netlify.com/api/v1';
const FORMS = { signups: 'early-access', tickets: 'support-ticket' };
// Where a sign-up or ticket was sent from, and the answers to "How did you hear about us?". Anything else is dropped.
const SOURCES = new Set(['website', 'app-ios', 'app-android']);
const HEARD = new Set(['search', 'social', 'friend', 'clinician', 'news', 'app-store', 'other']);
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const SUBMISSION_ID = /^[A-Za-z0-9_-]{6,64}$/; // Netlify's ids; this also keeps paths like ../ out
const EMAIL_RE = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)*\.[A-Za-z]{2,}$/;

class ApiError extends Error {
  constructor(code, status = 502) { super(code); this.code = code; this.status = status; }
}

const json = (status, body) => new Response(JSON.stringify(body), {
  status,
  headers: { 'content-type': 'application/json', 'cache-control': 'no-store' },
});

async function timed(url, init = {}, ms = 8000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  try {
    return await fetch(url, { ...init, signal: controller.signal });
  } catch (err) {
    throw new ApiError('unreachable');
  } finally {
    clearTimeout(timer);
  }
}

// Only pages on our own domains may call these: jachihealth.com, and this Netlify project's own addresses
// (including its deploy previews). Requests without an Origin header (same-site GETs) are fine.
function allowedOrigin(req, context) {
  const origin = req.headers.get('origin');
  if (!origin) return true;
  let host;
  try { host = new URL(origin).hostname; } catch { return false; }
  if (ALLOWED_HOSTS.test(host)) return true;
  const site = (context && context.site) || {};
  if (site.name && (host === `${site.name}.netlify.app` || host.endsWith(`--${site.name}.netlify.app`))) return true;
  try { return Boolean(site.url) && host === new URL(site.url).hostname; } catch { return false; }
}

function identity(req) {
  const ctx = globalThis.netlifyIdentityContext || {};
  const url = (ctx.url || new URL('/.netlify/identity', req.url).href).replace(/\/+$/, '');
  return { url, token: ctx.token || null };
}

function bearer(req) {
  const match = (req.headers.get('authorization') || '').match(/^Bearer\s+([A-Za-z0-9._~+/=-]+)$/);
  return match ? match[1] : null;
}

// The signed-in person, checked with the Identity service itself (it validates the token).
async function signedInUser(req) {
  const token = bearer(req);
  if (!token) return { status: 401, error: 'signed_out' };
  let res;
  try {
    res = await timed(`${identity(req).url}/user`, { headers: { Authorization: `Bearer ${token}` } });
  } catch {
    return { status: 502, error: 'identity_unreachable' };
  }
  if ([400, 401, 403, 404].includes(res.status)) return { status: 401, error: 'signed_out' };
  if (!res.ok) return { status: 502, error: 'identity_unreachable' };
  const user = await res.json().catch(() => null);
  if (!user || !user.id) return { status: 401, error: 'signed_out' };
  return { user };
}

async function identitySettings(req) {
  try {
    const res = await timed(`${identity(req).url}/settings`);
    return res.ok ? await res.json() : null;
  } catch {
    return null;
  }
}

function adminEmails() {
  return (process.env.ADMIN_EMAILS || SUPPORT_EMAIL)
    .split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
}

// Admins: anyone given the "admin" role in Netlify's Identity tab, or an account whose email is in
// ADMIN_EMAILS (the support email by default) that was created from an invitation sent in Netlify.
// The invitation matters: while registration is open, a stranger could create an account with the admin's
// address first. They can't confirm it, but Identity keeps the first password if the real owner signs up
// again and then confirms, which would let the stranger in. Only people with access to the Netlify project
// can send invitations, and an invitation can't be sent to an address that already has an account.
// Email-based access is also refused while Identity's Autoconfirm setting is on.
async function requireAdmin(req, settings) {
  const who = await signedInUser(req);
  if (!who.user) return who;
  const user = who.user;
  const roles = Array.isArray(user.app_metadata && user.app_metadata.roles) ? user.app_metadata.roles : [];
  if (roles.includes('admin')) return { user, via: 'role' };
  const email = String(user.email || '').toLowerCase();
  if (!email || !user.confirmed_at || !adminEmails().includes(email)) return { status: 403, error: 'not_admin' };
  if (!user.invited_at) return { status: 403, error: 'not_invited' };
  if (!settings) return { status: 502, error: 'identity_unreachable' };
  if (settings.autoconfirm) return { status: 403, error: 'autoconfirm_on' };
  return { user, via: 'email' };
}

// True when the person proved the email is theirs by opening a link we sent to it: a confirmation email
// (confirmation_sent_at) or an invitation (invited_at). Accounts confirmed automatically, while Identity's
// Autoconfirm setting was on, have neither.
function provedEmail(user) {
  return Boolean(user && user.confirmed_at && (user.confirmation_sent_at || user.invited_at));
}

// ---------- Identity admin (needs the operator token Netlify gives functions) ----------

async function identityAdmin(req, path, init = {}) {
  const { url, token } = identity(req);
  if (!token) throw new ApiError('identity_admin_unavailable', 503);
  return timed(`${url}/admin${path}`, { ...init, headers: { ...(init.headers || {}), Authorization: `Bearer ${token}` } });
}

async function listUsers(req) {
  const users = [];
  for (let page = 1; page <= 20; page++) {
    const res = await identityAdmin(req, `/users?per_page=100&page=${page}`);
    if (!res.ok) throw new ApiError('identity_admin_unavailable');
    const body = await res.json().catch(() => ({}));
    const batch = Array.isArray(body.users) ? body.users : [];
    users.push(...batch);
    if (batch.length < 100) break;
  }
  return users;
}

async function deleteUser(req, id) {
  if (!UUID.test(String(id))) throw new ApiError('bad_id', 400);
  const res = await identityAdmin(req, `/users/${encodeURIComponent(id)}`, { method: 'DELETE' });
  if (res.status === 404) return false;
  if (!res.ok) throw new ApiError('identity_admin_unavailable');
  return true;
}

function cleanUser(u) {
  const meta = u.user_metadata || {};
  const roles = Array.isArray(u.app_metadata && u.app_metadata.roles) ? u.app_metadata.roles : [];
  return {
    id: u.id,
    email: String(u.email || ''),
    confirmed: Boolean(u.confirmed_at),
    created_at: u.created_at || null,
    last_sign_in_at: u.last_sign_in_at || null,
    state: typeof meta.state === 'string' ? meta.state.slice(0, 2) : '',
    interests: Array.isArray(meta.interests) ? meta.interests.filter(x => typeof x === 'string').slice(0, 20) : [],
    language: meta.language === 'es' ? 'es' : 'en',
    updates: meta.updates !== false,
    admin: roles.includes('admin'),
  };
}

// ---------- Netlify Forms, through the Netlify API ----------

function apiToken() { return process.env.NETLIFY_API_TOKEN || ''; }
function siteId(context) { return (context && context.site && context.site.id) || process.env.SITE_ID || ''; }

async function netlify(path, init = {}) {
  if (!apiToken()) throw new ApiError('forms_not_connected', 503);
  const res = await timed(`${NETLIFY_API}${path}`, {
    ...init,
    headers: { ...(init.headers || {}), Authorization: `Bearer ${apiToken()}`, 'User-Agent': 'jachi-health-admin' },
  });
  if (res.status === 401 || res.status === 403) throw new ApiError('forms_unauthorized');
  return res;
}

async function formIds(context) {
  const id = siteId(context);
  if (!id) throw new ApiError('forms_unreachable');
  const res = await netlify(`/sites/${encodeURIComponent(id)}/forms`);
  if (!res.ok) throw new ApiError('forms_unreachable');
  const forms = await res.json().catch(() => []);
  const ids = {};
  for (const form of Array.isArray(forms) ? forms : []) {
    for (const [key, name] of Object.entries(FORMS)) if (form.name === name) ids[key] = form.id;
  }
  return ids;
}

async function submissions(formId) {
  const all = [];
  for (let page = 1; page <= 20; page++) {
    const res = await netlify(`/forms/${encodeURIComponent(formId)}/submissions?per_page=100&page=${page}`);
    if (!res.ok) throw new ApiError('forms_unreachable');
    const batch = await res.json().catch(() => []);
    if (!Array.isArray(batch)) break;
    all.push(...batch);
    if (batch.length < 100) break;
  }
  return all;
}

// Only the fields our forms collect. Netlify also stores each sender's IP address and browser details,
// which the admin console never needs, so they're left out.
function cleanSubmission(s, form) {
  const data = (s && s.data) || {};
  const text = (key, max = 2000) => (typeof data[key] === 'string' ? data[key].slice(0, max) : '');
  return {
    id: String(s.id || ''),
    form,
    created_at: s.created_at || null,
    email: text('email', 254) || String(s.email || '').slice(0, 254),
    name: text('first_name', 80) || text('name', 80),
    state: text('state', 2),
    interest: text('interest', 300),
    language: text('language', 5) === 'es' ? 'es' : 'en',
    source: SOURCES.has(text('source', 20)) ? text('source', 20) : '',
    heard: HEARD.has(text('heard', 20)) ? text('heard', 20) : '',
    // The ad that brought the sign-up (utm tags from the ad's link), letters, digits and a few separators only.
    ad: Object.fromEntries(['source', 'medium', 'campaign', 'term', 'content']
      .map(k => [k, text(`utm_${k}`, 100).replace(/[^\w .:|/+-]/g, '').trim()]).filter(([, v]) => v)),
    topic: text('topic', 80),
    message: text('message', 2000),
    include_chat: text('include_chat', 5) === 'yes',
    chat_transcript: text('chat_transcript', 6000),
  };
}

// Whether a submission id belongs to this site's sign-up or ticket form. The access token reaches every form
// in the Netlify account, so the console only deletes ids it finds here.
async function ourSubmission(context, id) {
  if (!SUBMISSION_ID.test(String(id))) throw new ApiError('bad_id', 400);
  for (const formId of Object.values(await formIds(context))) {
    if ((await submissions(formId)).some(s => String(s.id) === id)) return true;
  }
  return false;
}

async function deleteSubmission(id) {
  if (!SUBMISSION_ID.test(String(id))) throw new ApiError('bad_id', 400);
  const res = await netlify(`/submissions/${encodeURIComponent(id)}`, { method: 'DELETE' });
  if (res.status === 404) return false;
  if (!res.ok) throw new ApiError('forms_unreachable');
  return true;
}

// Delete every sign-up and ticket sent with this email. Returns how many were removed.
async function eraseSubmissions(context, email) {
  const wanted = String(email || '').trim().toLowerCase();
  if (!wanted) return 0;
  const ids = await formIds(context);
  let removed = 0;
  for (const [form, formId] of Object.entries(ids)) {
    for (const s of await submissions(formId)) {
      if (cleanSubmission(s, form).email.trim().toLowerCase() === wanted && await deleteSubmission(s.id)) removed++;
    }
  }
  return removed;
}

// Email alerts Netlify sends for every new form submission (sign-ups and tickets).
async function alertEmails(context) {
  const res = await netlify(`/hooks?site_id=${encodeURIComponent(siteId(context))}`);
  if (!res.ok) throw new ApiError('forms_unreachable');
  const hooks = await res.json().catch(() => []);
  return (Array.isArray(hooks) ? hooks : [])
    .filter(h => h && h.type === 'email' && h.event === 'submission_created' && h.data && h.data.email)
    .map(h => String(h.data.email));
}

async function addAlert(context, email) {
  const res = await netlify(`/hooks?site_id=${encodeURIComponent(siteId(context))}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ site_id: siteId(context), type: 'email', event: 'submission_created', data: { email } }),
  });
  if (!res.ok) throw new ApiError('forms_unreachable');
  return true;
}

function failure(err) {
  if (err instanceof ApiError) return json(err.status, { error: err.code });
  return json(500, { error: 'server_error' });
}

// ---------- Account deletion (src/functions/account.mjs) ----------
//   POST /api/account/delete   deletes the signed-in person's account, and every early-access sign-up and
//                              support ticket sent with their email (when NETLIFY_API_TOKEN is set).
// The sign-ups go first: if that fails, the account stays, so the person can try again.
// Sign-ups are only erased for an email the person proved is theirs (see provedEmail), and never while
// Identity's Autoconfirm setting is on. Otherwise someone could make an account with another person's
// email and use it to erase that person's sign-ups. In those cases only the account is deleted, and the
// page tells the person to email us about their sign-up.

export default async (req, context) => {
  if (req.method !== 'POST') return json(405, { error: 'method_not_allowed' });
  if (!allowedOrigin(req, context)) return json(403, { error: 'forbidden' });
  const who = await signedInUser(req);
  if (!who.user) return json(who.status, { error: who.error });
  if (!identity(req).token) return json(503, { error: 'identity_admin_unavailable' });
  try {
    let removed = 0;
    let forms = 'skipped';
    if (apiToken() && provedEmail(who.user)) {
      const settings = await identitySettings(req);
      if (settings && !settings.autoconfirm) {
        removed = await eraseSubmissions(context, who.user.email);
        forms = 'done';
      }
    }
    await deleteUser(req, who.user.id);
    return json(200, { ok: true, forms, removed });
  } catch (err) {
    return failure(err);
  }
};

export const config = {
  path: '/api/account/delete',
  rateLimit: { windowLimit: 10, windowSize: 60, aggregateBy: ['ip', 'domain'] },
};
